  'pv.and_tbl_h': "Resumen de datos en Android",
  'pv.and_th3': "Sale del teléfono",
  'pv.and_r1c1': "Fotos y tonos que eliges",
  'pv.and_r1c2': "Mostrar la foto de una alarma o una cuenta regresiva; hacer sonar tu tono. Guardados en el teléfono.",
  'pv.and_r2c1': "Eventos del calendario (lectura)",
  'pv.and_r2c2': "Poner alarma a tus eventos y detectar reuniones y direcciones.",
