  'nav.pricing': "Preise",
  'foot.tag': "Wecker, die auch klingeln, wenn das iPhone stumm ist, für alles, was zählt. Von Mathyu Solutions.",
  'foot.product': "Produkt",
  'foot.features': "Funktionen",
  'foot.privacy': "Privatsphäre",
  'foot.support': "Support",
